css:
.cosmic-plasma {
  width: 100%;
  height: 100%;
  background: conic-gradient(
    from 45deg,
    rgba(255, 0, 0, 0.4),
    rgba(0, 0, 255, 0.4),
    rgba(255, 0, 255, 0.4),
    rgba(0, 255, 0, 0.4),
    rgba(255, 0, 0, 0.4)
  );
  filter: url(#plasma-texture);
  position: relative;
}

.plasma-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.2) 0%,
    transparent 70%
  );
}
